    """Count lowercase words.

    Splits on whitespace, strips leading/trailing .,!? from each token,
    lowercases it, and returns a dictionary mapping words to their
    occurrence counts.
    """
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    counts = {}
    for token in text.split():
        cleaned = token.strip('.,!?')
        if not cleaned:
            continue
        word = cleaned.lower()
        counts[word] = counts.get(word, 0) + 1
    return counts

def dedupe(xs: list) -> list:
    """Remove duplicates, keeping the first occurrence of each element in original order."""
    seen = set()
    result = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            result.append(x)
    return result

def flatten(xs: list) -> list:
    """Flatten an arbitrarily nested list of ints, preserving left-to-right order."""
    result = []
    for item in xs:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

def median(nums: list) -> float:
    """Return the median of a non-empty list of numbers (mean of the two middle values for even length)."""
    if not nums:
        raise ValueError("median requires a non-empty list")
    sorted_nums = sorted(nums)
    n = len(sorted_nums)
    mid = n // 2
    if n % 2 == 1:
        return float(sorted_nums[mid])
    else:
        return (float(sorted_nums[mid - 1]) + float(sorted_nums[mid])) / 2.0

import json
from pathlib import Path

_TAX_RATES = None

def _load_rates():
    global _TAX_RATES
    if _TAX_RATES is None:
        config_path = Path(__file__).resolve().parent.parent / 'config' / 'tax_rates_2025.json'
        try:
            with open(config_path, 'r', encoding='utf-8') as f:
                _TAX_RATES = json.load(f)
        except Exception:
            _TAX_RATES = {}
    return _TAX_RATES

def state_tax(state: str, amount: float) -> float:
    """Sales tax owed on amount, using the rate table in config/tax_rates_2025.json."""
    rates = _load_rates()
    rate = rates.get(state.upper(), 0.0)
    tax = amount * rate
    return round(tax + 1e-12, 2)  # small epsilon to avoid floating point issues

def valid_parens(s: str) -> bool:
    """Return True if every (, [, { is closed by the matching bracket in the right order."""
    mapping = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in s:
        if ch in "([{":
            stack.append(ch)
        elif ch in ")]}":
            if not stack or stack[-1] != mapping[ch]:
                return False
            stack.pop()
    return not stack

def parse_price(s: str) -> float:
    """Parse a US-formatted price string like '$1,200.50' into a float.
    Handles inputs with or without a dollar sign, commas, decimals, and surrounding whitespace.
    """
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    # Strip whitespace
    s = s.strip()
    # Remove leading '$' if present
    if s.startswith('$'):
        s = s[1:]
    # Remove commas
    s = s.replace(',', '')
    # Now s should be a valid numeric string, possibly with a decimal point
    try:
        return float(s)
    except ValueError as e:
        raise ValueError(f"Unable to parse price from input: {s}") from e
